// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: keeps password managers (1Password, LastPass, Bitwarden, Dashlane) and the browser's own autofill off
//          every input, textarea, contenteditable (CodeMirror) and form in delulu-smash, including ones Reflex
//          adds later (MutationObserver). Opt in: put data-allow-autofill on the element or a parent.
//          Loaded from head_components in ui/ui.py.
// ---------------------------------------------------------------------------
(() => {
  const SELECTOR = "input, textarea, form, [contenteditable]";
  const IGNORE = { "data-1p-ignore": "", "data-lpignore": "true", "data-bwignore": "", "data-form-type": "other" };

  const mark = (el) => {
    if (el.hasAttribute("data-1p-ignore") || el.closest("[data-allow-autofill]")) return;
    for (const [name, value] of Object.entries(IGNORE)) el.setAttribute(name, value);
    if ((el.tagName === "INPUT" || el.tagName === "TEXTAREA") && !el.hasAttribute("autocomplete")) {
      el.setAttribute("autocomplete", "off");
    }
  };

  const scan = (node) => {
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    if (node.matches(SELECTOR)) mark(node);
    node.querySelectorAll(SELECTOR).forEach(mark);
  };

  const start = () => {
    scan(document.body);
    new MutationObserver((records) => {
      for (const record of records) record.addedNodes.forEach(scan);
    }).observe(document.body, { childList: true, subtree: true });
  };

  if (document.body) start();
  else document.addEventListener("DOMContentLoaded", start);
})();
